function eDash(){return `<div class="card hero row sp"><div><h1>Examiner workspace</h1><p class="mu">Create, schedule, monitor and publish examinations.</p></div><button class="btn" style="background:#fff;color:#4338ca" onclick="go('create')">+ New examination</button></div>
<div class="grid g4" style="margin:20px 0">${["Draft","Published","Ongoing","Completed"].map(s=>`<div class="stat"><b>${S.exams.filter(e=>e.st==s).length}</b>${s}</div>`).join("")}</div>
<div class="card tw"><table><tr><th>Exam</th><th>Status</th><th>Window</th><th>Candidates</th><th></th></tr>${S.exams.map(e=>`<tr><td><b>${e.title}</b><br><span class="mu sm">${e.code} · ${e.dur}m · ${e.marks} marks${e.rnd?" · randomised":""}</span></td><td><span class="pill ${pc(e.st)}">${e.st}</span></td><td class="sm">${e.win}</td><td>${e.cand.length}</td><td class="row"><button class="btn g s" onclick="start('${e.id}',1)">Sandbox</button>${e.st=="Draft"?`<button class="btn s" onclick="pubE('${e.id}')">Publish</button>`:e.st=="Completed"?`<button class="btn s" onclick="go('grade')">Results</button>`:""}</td></tr>`).join("")}</table></div>`}
function pubE(id){const e=S.exams.find(x=>x.id==id);if(!e.qs.length){e.qs=[1,2,3];e.cand=[3]}e.st="Published";e.win="Nov 29, 9:00 AM – 11:00 AM";R();toast("Published. Candidates can enter only inside the window.")}
function create(){return `<div style="max-width:760px;margin:auto"><a href="#" class="mu" onclick="go('dash');return false">← Back</a><div class="card col" style="margin-top:14px"><h1>New examination</h1><div class="grid g2"><label>Title<input id="t"><span class="err" id="e1"></span></label><label>Code<input id="c" placeholder="CS-101-MID"></label><label>Duration (minutes)<input id="d" type="number" value="45"><span class="err" id="e2"></span></label><label>Total marks<input id="m" type="number" value="30"></label><label>Opens<input type="datetime-local" id="s"></label><label>Closes<input type="datetime-local" id="x"><span class="err" id="e3"></span></label></div><label>Instructions<textarea rows="3"></textarea></label>
<label style="flex-direction:row;font-weight:500"><input type="checkbox" style="width:auto" id="r" checked>Randomise question and option order</label><label style="flex-direction:row;font-weight:500"><input type="checkbox" style="width:auto" checked>Balance paper difficulty (each paper draws the same easy/medium/hard mix)</label>
<div class="stat sm"><b style="font-size:15px">Review before publishing</b>Starts as <span class="pill gr">Draft</span>. Add questions from the bank and enrol candidates, then publish.</div><button class="btn" onclick="mk()">Save as draft</button></div></div>`}
function mk(){let ok=1;const v=(i,c,m)=>{$(i).textContent=c?"":m;if(c)ok=0};v("#e1",$("#t").value.trim().length>=3,"Title needs at least 3 characters.");v("#e2",+$("#d").value>0&&+$("#d").value<=300,"Enter 1–300 minutes.");v("#e3",!$("#s").value||!$("#x").value||$("#x").value>$("#s").value,"Closing time must be after opening.");if(!ok)return;S.exams.unshift({id:"n"+Date.now(),code:$("#c").value||"NEW-001",title:$("#t").value,desc:"",dur:+$("#d").value,marks:+$("#m").value,pass:Math.round($("#m").value/2),st:"Draft",win:"Unscheduled",qs:[],cand:[],rnd:$("#r").checked});toast("Draft saved");go("dash")}
function bank(){return `<div class="row sp"><h1>Question bank</h1><div class="row"><button class="btn g" onclick="modal(imp())">⬆ Bulk import</button></div></div><div class="card tw" style="margin-top:16px"><table><tr><th>Question</th><th>Type</th><th>Topic</th><th>Difficulty</th><th>Marks</th></tr>${qbank.map(q=>`<tr><td>${E(q.t)}</td><td><span class="pill gr">${q.ty=="mcq"?"Single":q.ty=="multi"?"Multi":"Written"}</span></td><td>${q.cat}</td><td><span class="pill ${q.d=="Easy"?"ok":q.d=="Hard"?"er":"wn"}">${q.d}</span></td><td>${q.m}</td></tr>`).join("")}</table></div>`}
function imp(){return `<h2>Import questions or candidates</h2><p class="mu sm" style="margin:4px 0 12px">Paste JSON: <code>[{"t":"Question","ty":"mcq","cat":"Topic","d":"Easy","m":2,"o":["A","B"],"a":[0]}]</code></p><textarea id="ij" rows="6"></textarea><div id="ie" class="col" style="margin:10px 0"></div><button class="btn" onclick="doImp()">Validate & import</button>`}
function doImp(){let j,er=[];try{j=JSON.parse($("#ij").value)}catch(e){$("#ie").innerHTML=`<span class="err">Invalid JSON: ${E(e.message)}</span>`;return}if(!Array.isArray(j))return $("#ie").innerHTML=`<span class="err">Expected a list of questions.</span>`;const g=[];j.forEach((q,i)=>{if(!q.t)er.push(`Row ${i+1}: missing question text`);else if(!["mcq","multi","text"].includes(q.ty))er.push(`Row ${i+1}: type must be mcq, multi or text`);else if(q.ty!="text"&&(!q.o||q.o.length<2||!q.a||!q.a.length))er.push(`Row ${i+1}: needs 2+ options and a correct answer`);else g.push({id:100+qbank.length+i,cat:"Imported",d:"Medium",m:1,o:[],a:[],ok:0,sk:0,...q})});qbank=[...qbank,...g];$("#ie").innerHTML=er.map(x=>`<span class="err">${x}</span>`).join("")+(g.length?`<span style="color:var(--ok)">Imported ${g.length} valid question(s).</span>`:"");if(g.length)R()}
